<script lang="ts">import {api} from '$lib/api';let step=1,sending=false,error='',success='';let form:any={fullName:'',nationality:'',dateOfBirth:'',phone:'',whatsapp:'',email:'',passportNumber:'',passportIssueDate:'',passportExpiryDate:'',passportCountry:'',companyName:'',businessType:'',position:'',website:'',purpose:'',targetCompany:'',preferredCountry:'',preferredDate:'',visitors:1,requirements:''};const fields:any={1:[['fullName','Full Name','text'],['nationality','Nationality','text'],['dateOfBirth','Date of Birth','date'],['phone','Phone Number','tel'],['whatsapp','WhatsApp Number','tel'],['email','Email','email']],2:[['passportNumber','Passport Number','text'],['passportIssueDate','Passport Issue Date','date'],['passportExpiryDate','Passport Expiry Date','date'],['passportCountry','Passport Issuing Country','text']],3:[['companyName','Company Name','text'],['businessType','Business Type','text'],['position','Position','text'],['website','Website','url']],4:[['purpose','Purpose of Visit','text'],['targetCompany','Factory / Supplier / Company','text'],['preferredCountry','Preferred Country','text'],['preferredDate','Preferred Date','date'],['visitors','Number of Visitors','number'],['requirements','Additional Requirements','textarea']]};async function submit(){sending=true;error='';try{await api('/applications',{method:'POST',body:JSON.stringify({type:'BUSINESS',fullName:form.fullName,email:form.email,phone:form.phone,details:form})});success='Your business visit application has been submitted.'}catch(e){error=e instanceof Error?e.message:'Submission failed'}finally{sending=false}}</script><svelte:head><title>Business Visit Application — Bengal Port</title></svelte:head><section class="page-hero"><div class="wrap"><span class="eyebrow">BUSINESS VISIT APPLICATION</span><h1>Plan your international visit.</h1><p>Complete the four short steps. Passport expiry information is required for travel planning.</p></div></section><section class="section"><div class="wrap appbox"><div class="progress">{#each ['Personal','Passport','Business','Visit'] as label,i}<button class:active={step===i+1} class:done={step>i+1} onclick={()=>step=i+1}><i>{i+1}</i><span>{label}</span></button>{/each}</div>{#if success}<p class="success">{success}</p>{:else}<form onsubmit={(e)=>{e.preventDefault();step<4?step++:submit()}}><h2>Step {step}: {['Personal information','Passport details','Business information','Visit details'][step-1]}</h2>{#if error}<p class="error">{error}</p>{/if}<div class="form-grid">{#each fields[step] as f}<div class="field" class:wide={f[2]==='textarea'}><label for={f[0]}>{f[1]} *</label>{#if f[2]==='textarea'}<textarea id={f[0]} bind:value={form[f[0]]} rows="4" required></textarea>{:else}<input id={f[0]} type={f[2]} bind:value={form[f[0]]} required min={f[0]==='visitors'?1:undefined}/>{/if}</div>{/each}</div><div class="actions">{#if step>1}<button type="button" class="btn back" onclick={()=>step--}>BACK</button>{/if}<button class="btn" disabled={sending}>{sending?'SUBMITTING…':step===4?'SUBMIT APPLICATION':'CONTINUE'}</button></div></form>{/if}</div></section><style>.appbox{max-width:980px;background:#fff;border-radius:20px;padding:40px;box-shadow:var(--shadow)}.progress{display:grid;grid-template-columns:repeat(4,1fr);margin-bottom:40px}.progress button{border:0;background:linear-gradient(#dce1e7,#dce1e7) center 17px/100% 2px no-repeat;color:#77808d}.progress i{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:#e5e8ec;margin:auto;font-style:normal;font-weight:800}.progress span{display:block;margin-top:8px;font-size:12px}.progress button.active i,.progress button.done i{background:var(--gold);color:var(--navy)}.progress button.active span{color:var(--navy);font-weight:800}.wide{grid-column:1/-1}.actions{display:flex;justify-content:flex-end;gap:12px;margin-top:28px}.back{background:#e6e8eb}@media(max-width:600px){.appbox{padding:22px}.progress span{font-size:10px}}</style>
